(function initSolfegeCountAudio(globalScope) {
    'use strict';

    const COUNT_AUDIO_MAP = {
        'one': 'data:audio/mp3;base64,',
        'two': 'data:audio/mp3;base64,',
        'three': 'data:audio/mp3;base64,',
        'four': 'data:audio/mp3;base64,',
        'five': 'data:audio/mp3;base64,',
        'six': 'data:audio/mp3;base64,',
        'seven': 'data:audio/mp3;base64,',
        'eight': 'data:audio/mp3;base64,',
        'sing': 'data:audio/mp3;base64,'
    };

    class SolfegeCountAudioBank {
        constructor() {
            this.buffers = new Map();
        }

        async getBuffer(word) {
            const normalized = (word || "").toLowerCase();
            if (this.buffers.has(normalized)) return this.buffers.get(normalized);
            const uri = COUNT_AUDIO_MAP[normalized];
            if (!uri) return null;
            const response = await fetch(uri);
            const arrayBuffer = await response.arrayBuffer();
            this.buffers.set(normalized, arrayBuffer);
            return arrayBuffer;
        }

        getDataUri(word) {
            return COUNT_AUDIO_MAP[(word || "").toLowerCase()] || null;
        }

        hasWord(word) {
            return !!COUNT_AUDIO_MAP[(word || "").toLowerCase()];
        }
    }

    globalScope.SolfegeCountAudioBank = SolfegeCountAudioBank;
})(typeof window !== "undefined" ? window : globalThis);
